"""Side-by-side harness: run the same planning scenario through a bulk
endpoint and through the equivalent one-by-one calls, then diff the result.

Everything goes through the HTTP API with the Django test client, on a
project created from the stock "scrum" template.
"""
import datetime
import json

from django.core import mail
from django.core.management import call_command

from tests import factories as f

API = "/api/v1/"


class World:
    def __init__(self, client, mode):
        from taiga.projects.models import Project
        from taiga.projects.notifications.choices import NotifyLevel
        from taiga.projects.notifications.services import create_notify_policy_if_not_exists

        self.c = client
        self.mode = mode
        self.tag = " [%s]" % mode
        self.calls = []

        self.owner = f.UserFactory.create()
        self.member = f.UserFactory.create()
        client.login(self.owner)

        r = self.api("post", "projects", {
            "name": "Planning" + self.tag,
            "description": "bulk vs single",
            "creation_template": 1,
            "is_private": True,
        }, setup=True)
        self.project = Project.objects.get(id=r.data["id"])

        # A second member who asked to be notified about everything.
        f.MembershipFactory.create(project=self.project, user=self.member,
                                   role=self.project.roles.get(name="Back"))
        policy = create_notify_policy_if_not_exists(self.project, self.member)
        policy.notify_level = NotifyLevel.all
        policy.save()

        self.api("post", "userstory-custom-attributes",
                 {"project": self.project.id, "name": "Client ref"}, setup=True)
        self.api("post", "task-custom-attributes",
                 {"project": self.project.id, "name": "Estimate"}, setup=True)

    # ---- plumbing -------------------------------------------------------
    def api(self, method, path, data=None, setup=False):
        self.c.login(self.owner)
        fn = getattr(self.c.json, method)
        r = fn(API + path, json.dumps(data) if data is not None else "")
        if setup:
            assert r.status_code in (200, 201, 204), (method, path, r.status_code,
                                                      getattr(r, "data", None))
        else:
            detail = None
            if r.status_code >= 400:
                detail = json.loads(json.dumps(getattr(r, "data", None), default=str))
            self.calls.append({"status": r.status_code, "error": detail})
        return r

    def refresh(self):
        self.project.refresh_from_db()

    # ---- lookups --------------------------------------------------------
    def us_status(self, name):
        return self.project.us_statuses.get(name=name)

    def task_status(self, name):
        return self.project.task_statuses.get(name=name)

    def sprint_obj(self, name):
        return self.project.milestones.get(name=name + self.tag)

    def us(self, subject):
        return self.project.user_stories.get(subject=subject)

    def tk(self, subject):
        return self.project.tasks.get(subject=subject)

    def iss(self, subject):
        return self.project.issues.get(subject=subject)

    # ---- setup helpers (always the one-by-one API, same in both worlds) --
    def sprint(self, name, offset=0):
        start = datetime.date.today() + datetime.timedelta(days=offset)
        self.api("post", "milestones", {
            "project": self.project.id, "name": name + self.tag,
            "estimated_start": str(start),
            "estimated_finish": str(start + datetime.timedelta(days=14)),
        }, setup=True)

    def story(self, subject, sprint=None, status=None, setup=True):
        data = {"project": self.project.id, "subject": subject}
        if sprint:
            data["milestone"] = self.sprint_obj(sprint).id
        if status:
            data["status"] = self.us_status(status).id
        return self.api("post", "userstories", data, setup=setup)

    def task(self, subject, story=None, sprint=None, status=None, setup=True):
        data = {"project": self.project.id, "subject": subject}
        if story:
            data["user_story"] = self.us(story).id
        if sprint:
            data["milestone"] = self.sprint_obj(sprint).id
        if status:
            data["status"] = self.task_status(status).id
        return self.api("post", "tasks", data, setup=setup)

    def issue(self, subject, sprint=None, closed=False, setup=True):
        data = {"project": self.project.id, "subject": subject}
        if sprint:
            data["milestone"] = self.sprint_obj(sprint).id
        if closed:
            data["status"] = self.project.issue_statuses.filter(is_closed=True).first().id
        return self.api("post", "issues", data, setup=setup)

    def patch_story(self, subject, setup=False, **fields):
        us = self.us(subject)
        fields["version"] = us.version
        return self.api("patch", "userstories/%s" % us.id, fields, setup=setup)

    def patch_task(self, subject, setup=False, **fields):
        t = self.tk(subject)
        fields["version"] = t.version
        return self.api("patch", "tasks/%s" % t.id, fields, setup=setup)

    def patch_issue(self, subject, setup=False, **fields):
        i = self.iss(subject)
        fields["version"] = i.version
        return self.api("patch", "issues/%s" % i.id, fields, setup=setup)

    # ---- state ----------------------------------------------------------
    def _hist(self, obj):
        from taiga.projects.history.models import HistoryEntry
        from taiga.projects.history.services import make_key_from_model_object
        qs = HistoryEntry.objects.filter(key=make_key_from_model_object(obj)).order_by("created_at")
        return [sorted((h.diff or {}).keys()) for h in qs]

    def _name(self, obj):
        return None if obj is None else obj.name.replace(self.tag, "")

    def snapshot(self):
        from taiga.projects.custom_attributes.models import (
            UserStoryCustomAttributesValues, TaskCustomAttributesValues)
        from taiga.timeline.models import Timeline

        self.refresh()
        p = self.project
        out = {"sprints": {}, "stories": {}, "tasks": {}, "issues": {}}

        out["backlog_order"] = [u.subject for u in
                                p.user_stories.filter(milestone__isnull=True).order_by("backlog_order", "id")]
        for m in p.milestones.order_by("name"):
            out["sprints"][self._name(m)] = {
                "closed": m.closed,
                "stories_in_order": [u.subject for u in m.user_stories.order_by("sprint_order", "id")],
                "tasks": sorted(t.subject for t in m.tasks.all()),
                "issues": sorted(i.subject for i in m.issues.all()),
            }
        for u in p.user_stories.order_by("subject"):
            out["stories"][u.subject] = {
                "sprint": self._name(u.milestone),
                "status": u.status.name if u.status else None,
                "is_closed": u.is_closed,
                "has_finish_date": u.finish_date is not None,
                "version": u.version,
                "modified_date": u.modified_date.isoformat(),
                "role_points_rows": u.role_points.count(),
                "custom_attr_row": UserStoryCustomAttributesValues.objects.filter(user_story=u).exists(),
                "has_ref": u.ref is not None,
                "history": self._hist(u),
                "tasks_in_order": [t.subject for t in u.tasks.order_by("us_order", "id")],
            }
        for t in p.tasks.order_by("subject"):
            out["tasks"][t.subject] = {
                "sprint": self._name(t.milestone),
                "story": t.user_story.subject if t.user_story else None,
                "story_sprint": self._name(t.user_story.milestone) if t.user_story else None,
                "status": t.status.name if t.status else None,
                "has_finished_date": t.finished_date is not None,
                "version": t.version,
                "modified_date": t.modified_date.isoformat(),
                "custom_attr_row": TaskCustomAttributesValues.objects.filter(task=t).exists(),
                "has_ref": t.ref is not None,
                "history": self._hist(t),
                "us_order": t.us_order,
            }
        for i in p.issues.order_by("subject"):
            out["issues"][i.subject] = {
                "sprint": self._name(i.milestone),
                "version": i.version,
                "modified_date": i.modified_date.isoformat(),
                "history": self._hist(i),
            }
        out["_timeline_rows"] = Timeline.objects.filter(project=p).count()
        out["_emails_to_member"] = len([m for m in mail.outbox if self.member.email in m.to])
        return out


def _delta(before, after):
    """Turn absolute counters into 'what the action did' so both worlds compare."""
    res = json.loads(json.dumps(after))
    for kind in ("stories", "tasks", "issues"):
        for subject, a in res[kind].items():
            b = before[kind].get(subject)
            if b is None:
                a["existed_before"] = False
                a.pop("modified_date")
                a.pop("us_order", None)
                continue
            a["existed_before"] = True
            a["version_bumped_by"] = a.pop("version") - b["version"]
            a["modified_date_changed"] = a.pop("modified_date") != b["modified_date"]
            a["new_history"] = a.pop("history")[len(b["history"]):]
            if "us_order" in a:
                a["us_order_changed"] = a.pop("us_order") != b["us_order"]
    res["timeline_rows_added"] = res.pop("_timeline_rows") - before["_timeline_rows"]
    res["emails_to_member"] = res.pop("_emails_to_member") - before["_emails_to_member"]
    return res


def _diff(a, b, path=""):
    out = []
    if isinstance(a, dict) and isinstance(b, dict):
        for k in sorted(set(a) | set(b)):
            out += _diff(a.get(k, "<absent>"), b.get(k, "<absent>"), "%s/%s" % (path, k))
    elif a != b:
        out.append((path, a, b))
    return out


def compare(client, title, setup, bulk, single):
    """setup(w) builds the starting point; bulk(w)/single(w) perform the action."""
    call_command("loaddata", "initial_project_templates", verbosity=0)
    results = {}
    for mode, action in (("bulk", bulk), ("single", single)):
        w = World(client, mode)
        setup(w)
        before = w.snapshot()
        w.calls = []
        action(w)
        after = w.snapshot()
        results[mode] = {"http": w.calls, "state": _delta(before, after), "start": before}

    diffs = _diff(results["bulk"]["state"], results["single"]["state"])
    print("\n" + "=" * 100)
    print(title)
    print("  bulk   HTTP:", [c["status"] for c in results["bulk"]["http"]],
          [c["error"] for c in results["bulk"]["http"] if c["error"]] or "")
    print("  single HTTP:", [c["status"] for c in results["single"]["http"]],
          [c["error"] for c in results["single"]["http"] if c["error"]] or "")
    if not diffs:
        print("  SAME: no differences in resulting state")
    for path, bv, sv in diffs:
        print("  DIFF %-58s bulk=%r  single=%r" % (path, bv, sv))
    return results, diffs

