    res["emails_to_member"] = res.pop("_emails_to_member") - before["_emails_to_member"]
    return res


def _diff(a, b, path=""):
    out = []
    if isinstance(a, dict) and isinstance(b, dict):
        for k in sorted(set(a) | set(b)):
            out += _diff(a.get(k, "<absent>"), b.get(k, "<absent>"), "%s/%s" % (path, k))
    elif a != b:
        out.append((path, a, b))
    return out


def compare(client, title, setup, bulk, single):
    """setup(w) builds the starting point; bulk(w)/single(w) perform the action."""
    call_command("loaddata", "initial_project_templates", verbosity=0)
    results = {}
    for mode, action in (("bulk", bulk), ("single", single)):
        w = World(client, mode)
        setup(w)
        before = w.snapshot()
        w.calls = []
        action(w)
        after = w.snapshot()
        results[mode] = {"http": w.calls, "state": _delta(before, after), "start": before}

    diffs = _diff(results["bulk"]["state"], results["single"]["state"])
    print("\n" + "=" * 100)
    print(title)
    print("  bulk   HTTP:", [c["status"] for c in results["bulk"]["http"]],
          [c["error"] for c in results["bulk"]["http"] if c["error"]] or "")
    print("  single HTTP:", [c["status"] for c in results["single"]["http"]],
          [c["error"] for c in results["single"]["http"] if c["error"]] or "")
    if not diffs:
        print("  SAME: no differences in resulting state")
    for path, bv, sv in diffs:
        print("  DIFF %-58s bulk=%r  single=%r" % (path, bv, sv))
    return results, diffs

